class Solution {
    fun smallestEquivalentString(s1:String,s2:String,baseStr:String):String{
        val parent=IntArray(26){
            it
        };
        fun find(xInput:Int):Int{
            var x=xInput;
            while(parent[x]!=x){
                parent[x]=parent[parent[x]];
                x=parent[x]
            };
            return x
        };
        for(i in s1.indices){
            val a=find(s1[i]-'a');
            val b=find(s2[i]-'a');
            parent[maxOf(a,b)]=minOf(a,b)
        };
        return baseStr.map{
            ('a'.code+find(it-'a')).toChar()
        }.joinToString("")
    }
}

